#!/usr/bin/env python3
import hashlib,json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]; base=ROOT/'results/experiment-c'
required=['c1/result.json','c1/arm_seed_target_metrics.csv','c1/paired_primary.csv','c1/candidate_structures/candidate_structure_index.csv','c1/candidate_structures/structure_comparison.csv','c1/candidate_structures/manifest.json','c1/candidate_structures/binary_30_candidates.png','c1/candidate_structures/continuous_30_candidates.png','c1/candidate_structures/md_validation_top20_by_arm.csv','md-validation/continuous_top20.csv','md-validation/binary_top20.csv','md-validation/legacy_polygen_hash20.csv','md-validation/md_batch_manifest.csv','md-validation/MD_VALIDATION_PROTOCOL.md','figures/c1_candidate_comparison.png','figures/c1_five_seed_publication.png','figures/c1_five_seed_publication.svg','figures/c1_five_seed_primary_effect.png','figures/c1_five_seed_primary_effect.svg','publication/c1_five_seed_summary.json','publication/c1_five_seed_arm_target_metrics.csv','publication/c1_five_seed_arm_metrics.csv','publication/c1_five_seed_paired_effects.csv','publication/c1_five_seed_effect_summary.csv','publication/c1_five_seed_controllability.csv','publication/c1_five_seed_target_summary.csv','publication/RESULTS_AND_DISCUSSION.md','publication/TABLES_AND_CAPTIONS.md','publication/POLYGEN_ALIGNMENT_TODO.md','c1b/result.json','c1b/metrics.csv','c1b/paired.csv','c2/result.json','c2/metrics.csv','c2/paired.csv','pedatamine/audit.json','pedatamine/conductivity_long.csv','hierarchical_demo.csv']
checks={p:(base/p).is_file() and (base/p).stat().st_size>0 for p in required}
c1_samples=list((base/'c1').glob('*-seed*/samples.csv')); checks['six_c1_sample_files']=len(c1_samples)==6; checks['c1_1800_samples']=sum(len(pd.read_csv(p)) for p in c1_samples)==1800; checks['c1b_1800_samples']=len(pd.read_csv(base/'c1b/samples.csv'))==1800; checks['c2_8100_samples']=len(pd.read_csv(base/'c2/samples.csv'))==8100
pair=pd.read_csv(base/'c1/paired_primary.csv'); checks['c1_three_paired_seeds']=set(pair.seed)=={17,42,907}; demo=pd.read_csv(base/'hierarchical_demo.csv'); checks['hierarchical_joint_claims_blocked']=bool((~demo.eligible_for_physical_claim).all())
index=pd.read_csv(base/'c1/candidate_structures/candidate_structure_index.csv'); checks['c1_candidate_panel_is_stratified']=bool(len(index)==60 and set(index.seed)=={17,42,202,303,907} and index.groupby(['arm','seed','target']).size().eq(2).all())
extra_samples=list((base/'extra-seeds/seeds202-303').glob('*-seed*/samples.csv')); checks['four_extra_c1_sample_files']=len(extra_samples)==4; checks['c1_five_seed_3000_samples']=sum(len(pd.read_csv(p)) for p in c1_samples+extra_samples)==3000
pub_pair=pd.read_csv(base/'publication/c1_five_seed_paired_effects.csv'); checks['c1_five_paired_seeds']=set(pub_pair.seed)=={17,42,202,303,907}; checks['c1_all_five_hit_deltas_positive']=bool((pub_pair.delta_hit_rate>0).all())
mdq=pd.read_csv(base/'c1/candidate_structures/md_validation_top20_by_arm.csv'); checks['md_queue_has_20_per_arm']=bool(mdq.groupby('arm').size().eq(20).all())
md_manifest=pd.read_csv(base/'md-validation/md_batch_manifest.csv'); checks['md_manifest_has_three_20_structure_cohorts']=bool(md_manifest.groupby('cohort').size().eq(20).all()); checks['md_manifest_is_unrun']=bool(md_manifest.status.eq('PLANNED_NOT_RUN').all())
manifest={'status':'pass' if all(checks.values()) else 'fail','checks':checks,'artifacts':{p:hashlib.sha256((base/p).read_bytes()).hexdigest() for p in required}}
(base/'verification.json').write_text(json.dumps(manifest,indent=2)+'\n'); print(json.dumps(manifest,indent=2)); raise SystemExit(0 if manifest['status']=='pass' else 1)
